import { GameTask } from './GameTask';
import type { ISlotGameMain } from '../types/ISlotGameMain';
import type { GameViewAdapter } from '../ui/GameViewAdapter';
import AppAudio from '../audio/AppAudio';
import { EFFECTSMAP } from '../audio/AudioConfig';
import { skipWait } from '../controllers/SkipWait';

/** 對應 SGTask_Scatter（觸發免費遊戲時的 scatter 中獎演出，原 GameMain_1001.playScatterWin）。 */
export async function playScatterWin(game: ISlotGameMain<GameViewAdapter>, cols: number[][]): Promise<void> {
    AppAudio.getInstance().playEffect(EFFECTSMAP.FG_TRIGGER);
    game.forEachView((v) => {
        const reels = v.slotMachineView?.reelViews;
        for (let col = 0; col < cols.length; col++) {
            for (let row = 0; row < cols[col].length; row++) {
                if (game.definition.symbols.resolve(cols[col][row]).kind === 'scatter') reels?.[col]?.playScatterWin(row);
            }
        }
    });
    await skipWait(game, 1.2);
}

export class ScatterWinTask extends GameTask {
    constructor(
        private readonly game: ISlotGameMain<GameViewAdapter>,
        private readonly cols: number[][]
    ) {
        super();
    }

    protected onStart(): void {
        playScatterWin(this.game, this.cols)
            .catch((error) => console.warn('[ScatterWinTask] failed', error))
            .finally(() => this.finish());
    }
}
